//! The End: island height field (`minecraft:end_islands` density function) and the End biome source.
//!
//! Behaviour follows the publicly documented End generation (main island of radius ~100 blocks
//! around the origin, outer islands placed on a 2-block-per-cell grid wherever a simplex noise
//! is below -0.9 more than 64 cells (1024 blocks) out), verified against vanilla 26.2 End worlds
//! generated by the server jar (`tools/parity.sh --end`, NOTES.md "The End").

use crate::noise::SimplexNoise;
use crate::random::{JavaRandom, Rng};

/// Island noise of a world seed.
pub fn island_noise(seed: i64) -> SimplexNoise {
    let mut r = JavaRandom::new(seed);
    r.consume(17292);
    SimplexNoise::new(&mut r)
}

/// Island height at cell (i, j) = block / 8 (Java integer division), in float like the game
/// (the float rounding shapes far-out islands).
pub fn height_value(n: &SimplexNoise, i: i32, j: i32) -> f32 {
    let k = i / 2;
    let l = j / 2;
    let m = i % 2;
    let o = j % 2;
    let mut f = 100.0f32 - ((i as i64 * i as i64 + j as i64 * j as i64) as f32).sqrt() * 8.0;
    f = f.clamp(-100.0, 80.0);
    for dx in -12i32..=12 {
        for dz in -12i32..=12 {
            let q = (k + dx) as i64;
            let r = (l + dz) as i64;
            if q * q + r * r > 4096 && n.get_2d(q as f64, r as f64) < -0.9 {
                let g = ((q as f32).abs() * 3439.0 + (r as f32).abs() * 147.0) % 13.0 + 9.0;
                let h = (m - dx * 2) as f32;
                let s = (o - dz * 2) as f32;
                let t = (100.0 - (h * h + s * s).sqrt() * g).clamp(-100.0, 80.0);
                f = f.max(t);
            }
        }
    }
    f
}

/// The `end_islands` density at a block position (independent of y).
pub fn density(n: &SimplexNoise, x: i32, z: i32) -> f64 {
    (height_value(n, x / 8, z / 8) as f64 - 8.0) / 128.0
}

/// End biome kinds, in the order [`biome_names`].
pub const BIOMES: [&str; 5] = [
    "the_end",
    "end_highlands",
    "end_midlands",
    "small_end_islands",
    "end_barrens",
];

/// Biome (index into [`BIOMES`]) at a quart position: the main island within 64 chunks of the
/// origin, elsewhere chosen from the island density at the centre of the chunk.
pub fn biome(n: &SimplexNoise, qx: i32, qz: i32) -> usize {
    let (cx, cz) = ((qx * 4) >> 4, (qz * 4) >> 4);
    if (cx as i64) * (cx as i64) + (cz as i64) * (cz as i64) <= 4096 {
        return 0;
    }
    let d = density(n, (cx * 2 + 1) * 8, (cz * 2 + 1) * 8);
    if d > 0.25 {
        1
    } else if d >= -0.0625 {
        2
    } else if d < -0.21875 {
        3
    } else {
        4
    }
}
